// Replace this simulated trend dataset with a live YouTube Data API v3 or Apify HTTP Request node
const config = $input.first().json;
const niche = config.niche || 'Next.js & AI Coding Workflows';

const sampleTrending = [
  {
    title: `Stop Writing Boilerplate: ${niche} in 5 Minutes`,
    views: 420000,
    subscribers: 18500,
    hookFirst3Sec: 'I deleted 600 lines of backend code and replaced it with 1 webhook.',
    commentGap: 'Viewers are asking how to handle retries and local testing safely.'
  },
  {
    title: `3 Mistakes Everyone Makes With ${niche}`,
    views: 285000,
    subscribers: 42000,
    hookFirst3Sec: 'If your automation breaks at 2 AM, this setting is why.',
    commentGap: 'No one showed the exact JSON template to import.'
  }
];

const scored = sampleTrending.map((item) => ({
  ...item,
  outlierMultiplier: Number((item.views / item.subscribers).toFixed(1))
})).sort((a, b) => b.outlierMultiplier - a.outlierMultiplier);

return [{
  json: {
    ...config,
    topOutlier: scored[0],
    analyzedCount: scored.length,
    winningHookPattern: 'Contrarian deletion / simplification hook + visual before/after'
  }
}];

